#ifdef GL_ES
precision mediump float;
#endif

#define MAX_STEPS 200
#define EPS 0.001
#define FAR 100.0

float hash12(vec2 p){
    float h = dot(p, vec2(127.1, 311.7));
    return fract(sin(h) * 43758.5453);
}

vec3 starBackground(vec2 fragCoord, vec3 rd) {
    float t = rd.y * 0.5 + 0.5;
    vec3 col = mix(vec3(0.01, 0.0, 0.05), vec3(0.2, 0.0, 0.3), t);
    float starVal = hash12(fragCoord.xy);
    if(starVal > 0.995) {
        float intensity = smoothstep(0.995, 1.0, starVal);
        col += vec3(intensity * 1.5);
    }
    return col;
}

struct SDFResult {
    float dist;
    float matID;
};

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdTorus(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

SDFResult unionSDF(SDFResult a, SDFResult b) {
    if (a.dist < b.dist) {
        return a;
    } else {
        return b;
    }
}

SDFResult mapSceneFull(vec3 p) {
    float time = iTime;
    SDFResult mainSphere = SDFResult(sdSphere(p, 0.5), 1.0);
    SDFResult mainRing   = SDFResult(sdTorus(p, vec2(0.7, 0.1)), 2.0);
    SDFResult mainPlanet = unionSDF(mainSphere, mainRing);
    vec3 centerA = vec3(1.5 * cos(time), 0.0, 1.5 * sin(time));
    float distA = sdSphere(p - centerA, 0.2);
    SDFResult planetA = SDFResult(distA, 3.0);
    vec3 centerB = vec3(2.0 * cos(0.7*time), 0.3*sin(time), 2.0 * sin(0.7*time));
    float distB = sdSphere(p - centerB, 0.3);
    SDFResult planetB = SDFResult(distB, 4.0);
    SDFResult res = unionSDF(mainPlanet, planetA);
    res = unionSDF(res, planetB);
    return res;
}

float mapDistance(vec3 p) {
    return mapSceneFull(p).dist;
}

vec3 calcNormal(vec3 p) {
    float d = mapDistance(p);
    const float h = 0.0005;
    vec3 n = vec3(
        mapDistance(p + vec3(h,0,0)) - d,
        mapDistance(p + vec3(0,h,0)) - d,
        mapDistance(p + vec3(0,0,h)) - d
    );
    return normalize(n);
}

float rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t*rd;
        float dist = mapDistance(p);
        if(abs(dist) < EPS) return t;
        t += dist;
        if(t > FAR) break;
    }
    return t;
}

vec3 getColorByID(float mID, vec3 pos, float time) {
    vec3 baseColor;
    if(mID < 1.5) {
        baseColor = vec3(0.8, 0.4, 0.3);
    }
    else if(mID < 2.5) {
        baseColor = vec3(0.6, 0.6, 0.8);
    }
    else if(mID < 3.5) {
        baseColor = vec3(0.3, 0.7, 0.4);
    }
    else {
        baseColor = vec3(0.8, 0.7, 0.3);
    }
    float pattern = sin(pos.x*5.0 + time*0.5) * sin(pos.z*5.0 - time*0.4);
    float pattern2 = cos(pos.y*4.0 + pos.x*3.0 - time*0.8);
    float mixVal = 0.1 * (pattern + pattern2);
    return baseColor + mixVal;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    float time = iTime * 0.6;
    vec3 ro = vec3(3.0*cos(time), 1.5, 3.0*sin(time));
    vec3 lookAt = vec3(0.0, 0.0, 0.0);
    vec3 cw = normalize(lookAt - ro); 
    vec3 cp = vec3(0.0, 1.0, 0.0);
    vec3 cu = normalize(cross(cw, cp));
    vec3 cv = cross(cu, cw);
    vec3 rd = normalize(uv.x*cu + uv.y*cv + cw);
    float t = rayMarch(ro, rd);
    vec3 col;
    if(t > FAR) {
        col = starBackground(fragCoord.xy, rd);
    } else {
        vec3 p = ro + t*rd;
        SDFResult hit = mapSceneFull(p);
        float mID = hit.matID;
        vec3 n = calcNormal(p);
        vec3 lightDir = normalize(vec3(0.3, 0.7, 0.4));
        float diff = max(dot(n, lightDir), 0.0);
        vec3 baseColor = getColorByID(mID, p, time);
        vec3 ambient = baseColor * 0.2;
        vec3 diffuse = baseColor * diff;
        col = ambient + diffuse;
        float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.0);
        col += 0.3 * rim * vec3(0.5, 0.7, 1.0);
        float fogFactor = exp(-0.05 * t * t);
        vec3 bg = starBackground(fragCoord.xy, rd);
        col = mix(bg, col, fogFactor);
    }
    fragColor = vec4(col, 1.0);
}
